css:
.scene2 {
  background: transparent;
  border-radius: 0;
  box-shadow: none;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 0;
  width: 100%;
  height: 100%;
  min-height: 100vh;
  overflow: hidden;
  position: relative;
}
.icon-wrap {
  position: relative;
  width: 180px;
  height: 180px;
  margin-bottom: 44px;
}
.dash-ring {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 2px dashed rgba(255,255,255,0.5);
  border-top-color: transparent;
  border-left-color: transparent;
  animation: spinCW 4s linear infinite;
}
.dash-ring2 {
  position: absolute;
  inset: 10px;
  border-radius: 50%;
  border: 1.5px dashed rgba(255,255,255,0.25);
  border-bottom-color: transparent;
  border-right-color: transparent;
  animation: spinCCW 6s linear infinite;
}
@keyframes spinCW  { to { transform: rotate(360deg); } }
@keyframes spinCCW { to { transform: rotate(-360deg); } }
.solid-ring {
  position: absolute;
  top: 50%; left: 50%;
  width: 106px; height: 106px;
  margin: -53px 0 0 -53px;
  border-radius: 50%;
  border: 2px solid rgba(255,255,255,0.55);
  animation: ringPulse 3s ease-in-out infinite;
}
@keyframes ringPulse {
  0%,100% { transform: scale(1); opacity: 0.55; }
  50%      { transform: scale(1.08); opacity: 0.9; }
}
.core {
  position: absolute;
  top: 50%; left: 50%;
  width: 76px; height: 76px;
  margin: -38px 0 0 -38px;
  border-radius: 50%;
  background: rgba(255,255,255,0.12);
  display: flex; align-items: center; justify-content: center;
  animation: corePulse 3s ease-in-out infinite;
}
@keyframes corePulse {
  0%,100% { background: rgba(255,255,255,0.12); }
  50%      { background: rgba(255,255,255,0.22); }
}
.compass {
  width: 36px; height: 36px;
  animation: compassSpin 6s ease-in-out infinite;
}
@keyframes compassSpin {
  0%   { transform: rotate(0deg); }
  25%  { transform: rotate(90deg); }
  50%  { transform: rotate(180deg); }
  75%  { transform: rotate(270deg); }
  100% { transform: rotate(360deg); }
}
.scan-line {
  position: absolute;
  top: 50%; left: 50%;
  width: 90px; height: 1.5px;
  margin: 0 0 0 -45px;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.7), transparent);
  transform-origin: left center;
  animation: radar 3s linear infinite;
  border-radius: 2px;
}
@keyframes radar {
  from { transform: rotate(0deg); opacity: 1; }
  to   { transform: rotate(360deg); opacity: 1; }
}
.ripple {
  position: absolute;
  top: 50%; left: 50%;
  width: 106px; height: 106px;
  margin: -53px 0 0 -53px;
  border-radius: 50%;
  border: 1.5px solid rgba(255,255,255,0.35);
  animation: rippleOut 3s ease-out infinite;
}
.ripple2 {
  animation-delay: 1.5s;
}
@keyframes rippleOut {
  0%   { transform: scale(0.9); opacity: 0.6; }
  100% { transform: scale(2.2); opacity: 0; }
}
.particles2 {
  position: absolute; inset: 0;
  pointer-events: none;
}
.pt {
  position: absolute;
  border-radius: 50%;
  background: rgba(255,255,255,0.15);
  animation: floatPt var(--d) ease-in-out infinite var(--dl);
}
@keyframes floatPt {
  0%,100% { transform: translateY(0); opacity: 0.15; }
  50%      { transform: translateY(-16px); opacity: 0.3; }
}
.title2 {
  color: #fff;
  font-size: 26px;
  font-weight: 700;
  text-align: center;
  margin: 0 0 14px;
  font-family: sans-serif;
  animation: fadeUp2 1s ease 0.3s both;
}
.subtitle2 {
  color: rgba(255,255,255,0.78);
  font-size: 15px;
  text-align: center;
  line-height: 1.6;
  max-width: 260px;
  margin: 0;
  font-family: sans-serif;
  animation: fadeUp2 1s ease 0.5s both;
}
@keyframes fadeUp2 {
  from { opacity: 0; transform: translateY(14px); }
  to   { opacity: 1; transform: translateY(0); }
}
